export function escapeHtml(string) {
	return string
		.replace(/&/g, '&amp;')
		.replace(/"/g, '&quot;')
		.replace(/'/g, '&#39;')
		.replace(/</g, '&lt;')
		.replace(/>/g, '&gt;');
}

export function unescapeHtml(htmlString) {
	return htmlString
		.replace(/&gt;/g, '>')
		.replace(/&lt;/g, '<')
		.replace(/&#39;/g, '\'')
		.replace(/&quot;/g, '"')
		.replace(/&amp;/g, '&');
}
